SELECT CUST_INFO_ID, TO_CHAR(SNAPSHOT_DATE, 'MM/DD/YYYY') AS SNAPSHOT_DATE, INFLOW_VARIANCE_30D, CASH_RUNWAY_DAYS_ESTIMATED, SPENDING_VOLATILITY_CV_60D, DEBT_SERVICE_PROXY_RATIO, NSF_EVENT_RATE_60D, ZERO_BALANCE_DAYS_RATIO_30D, TARGET_ABILITY FROM PIO_COLL_AI_ABILITY_MART WHERE DAY_DATE = TO_DATE(:day_date, 'YYYY-MM-DD')